/**
 * @file tests/tsconfig_solution_refs.test.ts
 * @description Guard `tsconfig.workspaces.json`, the project-reference solution
 * that `typecheck:ws` runs with `bun check -b`. A workspace tsconfig silently
 * left out of the solution drops out of the type gate.
 */

import { describe, expect, test } from "bun:test";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..");
const SOLUTION = join(ROOT, "tsconfig.workspaces.json");

/**
 * Generated by the external `nsh` tool: `packages/nsh-desk/.nsh/types` does not
 * exist in a fresh checkout, so its project cannot be referenced here. It is
 * checked by the dedicated NSH CI job instead.
 */
const GENERATED_PACKAGES = new Set(["packages/nsh-desk"]);

interface Solution {
  readonly references?: ReadonlyArray<{ readonly path?: string }>;
}

function projectRefs(): string[] {
  const solution = JSON.parse(readFileSync(SOLUTION, "utf8")) as Solution;
  return (solution.references ?? [])
    .map((entry) => entry.path)
    .filter((path): path is string => typeof path === "string");
}

function packageDirOf(ref: string): string {
  return ref.replace(/^\.\//, "").replace(/\/tsconfig\.json$/, "");
}

describe("tsconfig.workspaces.json", () => {
  test("references at least one project and every referenced tsconfig exists", () => {
    const refs = projectRefs();
    expect(refs.length).toBeGreaterThan(0);

    const missing = refs.filter((ref) => !existsSync(join(ROOT, ref)));
    expect(missing).toEqual([]);
  });

  test("has no duplicate project references", () => {
    const refs = projectRefs();
    expect(new Set(refs).size).toBe(refs.length);
  });

  test("every workspace tsconfig is referenced or explicitly generated", () => {
    const referenced = new Set(projectRefs().map(packageDirOf));
    const packagesDir = join(ROOT, "packages");
    const omitted: string[] = [];

    for (const entry of readdirSync(packagesDir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const rel = `packages/${entry.name}`;
      if (!existsSync(join(ROOT, rel, "tsconfig.json"))) continue;
      if (GENERATED_PACKAGES.has(rel)) continue;
      if (!referenced.has(rel)) omitted.push(rel);
    }

    expect(omitted).toEqual([]);
  });
});
